package com.gymmind.booking.application; import com.gymmind.audit.application.AuditRecorder; import com.gymmind.audit.domain.*; import com.gymmind.booking.domain.model.*; import com.gymmind.booking.domain.repository.BookingRepository; import com.gymmind.course.domain.model.Course; import com.gymmind.course.domain.repository.CourseRepository; import com.gymmind.iam.domain.model.RoleCode; import com.gymmind.shared.error.*; import com.gymmind.shared.security.CurrentActor; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.util.Map; @Service public class DefaultBookingService implements BookingService{private final CourseRepository courses;private final BookingRepository bookings;private final AuditRecorder audit;public DefaultBookingService(CourseRepository c,BookingRepository b,AuditRecorder a){courses=c;bookings=b;audit=a;}@Override @Transactional public void book(CurrentActor a,BookCourseCommand c){if(a==null||a.tenantId()==null||!a.roles().contains(RoleCode.GYM_ADMIN)||!a.hasPermission("booking:write"))throw new BusinessException(ErrorCode.FORBIDDEN);if(c==null||c.tenantId()!=null&&!a.tenantId().equals(c.tenantId()))throw new BusinessException(ErrorCode.FORBIDDEN);Course course=courses.findByTenantIdAndId(a.tenantId(),c.courseId()).orElseThrow(()->new BusinessException(ErrorCode.RESOURCE_NOT_FOUND));if(bookings.findByTenantIdAndMemberIdAndCourseId(a.tenantId(),c.memberId(),c.courseId()).isPresent())return;try{course.reserve();}catch(IllegalStateException e){throw new BusinessException(ErrorCode.CONFLICT);}bookings.save(Booking.create(a.tenantId(),c.memberId(),c.courseId()));audit.record(new AuditEvent("BOOKING_CREATED","BOOKING",c.courseId(),AuditResult.SUCCESS,"booking-service",Map.of()));}}
